-- Disposable MySQL integration fixture only. Never a production migration.
CREATE DATABASE IF NOT EXISTS askxuan_account_test;
CREATE DATABASE IF NOT EXISTS askxuan_admin_test_auth_tx;
CREATE DATABASE IF NOT EXISTS askxuan_user;
CREATE DATABASE IF NOT EXISTS askxuan_auth;
CREATE DATABASE IF NOT EXISTS askxuan_payment;
CREATE DATABASE IF NOT EXISTS askxuan_temple;
CREATE DATABASE IF NOT EXISTS askxuan_master;
CREATE TABLE IF NOT EXISTS askxuan_user.user (
id BIGINT PRIMARY KEY AUTO_INCREMENT,mobile VARCHAR(32),password VARCHAR(255) NOT NULL DEFAULT '',nickname VARCHAR(64) NOT NULL DEFAULT '',avatar VARCHAR(500) NOT NULL DEFAULT '',gender INT NOT NULL DEFAULT 0,birthday DATE NULL,region VARCHAR(64) NOT NULL DEFAULT '',bio VARCHAR(512) NOT NULL DEFAULT '',status INT NOT NULL DEFAULT 1,authz_version BIGINT NOT NULL DEFAULT 0,create_time DATETIME DEFAULT CURRENT_TIMESTAMP,update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS askxuan_auth.auth_identity(domain VARCHAR(16) NOT NULL,user_id BIGINT NOT NULL,username VARCHAR(32) NOT NULL,email VARCHAR(254) NOT NULL,password_hash VARCHAR(255) NOT NULL DEFAULT '',agreement_version VARCHAR(32) NOT NULL DEFAULT '',verified_at DATETIME NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(domain,user_id),UNIQUE(domain,username),UNIQUE(domain,email));
CREATE TABLE IF NOT EXISTS askxuan_payment.payment(id BIGINT PRIMARY KEY,user_id VARCHAR(64) NOT NULL,order_type VARCHAR(32) NOT NULL,order_no VARCHAR(64) NOT NULL,amount DECIMAL(12,2) NOT NULL,channel VARCHAR(16) NOT NULL,status VARCHAR(24) NOT NULL);
CREATE TABLE IF NOT EXISTS askxuan_payment.refund(id BIGINT PRIMARY KEY,payment_id BIGINT NOT NULL,amount DECIMAL(12,2) NOT NULL,status VARCHAR(24) NOT NULL);
CREATE TABLE IF NOT EXISTS askxuan_auth.role(id BIGINT PRIMARY KEY,name VARCHAR(64) NOT NULL,code VARCHAR(64) NOT NULL UNIQUE,description VARCHAR(255) NOT NULL DEFAULT '',authz_scope VARCHAR(16) NOT NULL DEFAULT 'platform',authz_version BIGINT NOT NULL DEFAULT 0,create_time DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS askxuan_auth.admin_account(id BIGINT PRIMARY KEY,account VARCHAR(64) NOT NULL,password VARCHAR(255) NOT NULL DEFAULT '',name VARCHAR(64) NOT NULL DEFAULT '',role_id BIGINT NOT NULL,authz_version BIGINT NOT NULL DEFAULT 0,platform_disabled TINYINT(1) NOT NULL DEFAULT 0,temple_id VARCHAR(16) NOT NULL DEFAULT '',master_id VARCHAR(16) NOT NULL DEFAULT '',shop_id BIGINT NOT NULL DEFAULT 0,status VARCHAR(16) NOT NULL,last_login_time DATETIME NULL,create_time DATETIME DEFAULT CURRENT_TIMESTAMP,update_time DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS askxuan_auth.master_invitation(id BIGINT PRIMARY KEY,account_id BIGINT NOT NULL UNIQUE,temple_code VARCHAR(16) NOT NULL,master_code VARCHAR(16) NOT NULL,email VARCHAR(254) NOT NULL,username VARCHAR(32) NOT NULL,status VARCHAR(16) NOT NULL);
CREATE TABLE IF NOT EXISTS askxuan_temple.temple(id BIGINT PRIMARY KEY,code VARCHAR(16) NOT NULL UNIQUE,name VARCHAR(64) NOT NULL,status VARCHAR(16) NOT NULL,auth_status VARCHAR(16) NOT NULL DEFAULT 'certified',platform_status VARCHAR(16) NOT NULL DEFAULT 'normal',shelf_status VARCHAR(16) NOT NULL DEFAULT 'on_shelf');
CREATE TABLE IF NOT EXISTS askxuan_master.master(id BIGINT PRIMARY KEY,code VARCHAR(16) NOT NULL UNIQUE,dharma_name VARCHAR(64) NOT NULL,temple_code VARCHAR(16) NOT NULL DEFAULT '',auth_status VARCHAR(16) NOT NULL,platform_status VARCHAR(16) NOT NULL,shelf_status VARCHAR(16) NOT NULL,manage_by VARCHAR(16) NOT NULL DEFAULT 'temple');

CREATE TABLE IF NOT EXISTS askxuan_temple.temple_admin(temple_code VARCHAR(16) NOT NULL,account_id BIGINT NOT NULL,role VARCHAR(32) NOT NULL,PRIMARY KEY(temple_code,account_id));
